Bitmap Texture_Enemy01 = Bitmap(18,24,Texture_Enemy01_d);
Bitmap Texture_Enemy02 = Bitmap(18,24,Texture_Enemy02_d);
Bitmap Texture_Enemy10 = Bitmap(18,24,Texture_Enemy10_d);
Bitmap Texture_Enemy11 = Bitmap(18,24,Texture_Enemy11_d);
