Enemy::Enemy(char EnemyType, double X, double Y, int HP,double Speed = 0,int Direction = 0){
  this->EnemyType=EnemyType;
  this->X=X;
  this->Y=Y;
  this->HP=HP;
  this->Speed=Speed;
  this->Direction=Direction;
  Type=3;
  Init();
}
void Enemy::Init(){
  switch(EnemyType){
    case 0:
    Width=18;
    Height=24;
    Texture = &Texture_Enemy00;
    HitboxSize = 8;
    break;
    case 1:
    Width=18;
    Height=24;
    Texture = &Texture_Enemy10;
    HitboxSize = 8;
    break;
    case 100:
    Width=48;
    Height=48;
    Texture=&Texture_Boss0;
    HitboxSize=16;
  }
}
void Enemy::Loop(){

  if(EnemyType == 0){
    if(Ticks % 20 == 0){
      switch((Ticks / 20)%3){
        case 0:
        Texture = &Texture_Enemy00;
        break;
        case 1:
        Texture = &Texture_Enemy01;
        break;
        case 2:
        Texture = &Texture_Enemy02;
        break;
      }
    }
  }
  else if(EnemyType == 1){
    if(Ticks % 15 == 0){
      switch((Ticks / 15)%3){
        case 0:
        Texture = &Texture_Enemy10;
        break;
        case 1:
        Texture = &Texture_Enemy11;
        break;
        case 2:
        Texture = &Texture_Enemy12;
        break;
      }
    }
  }
  if(WaveID==1){
    Wave1();
  }
  else if(WaveID==2){
    Wave2();
  }
  else if(WaveID==3){
    Wave3();
  }
  else if(WaveID==100){
    Boss0();
  }
  Move();
  Ticks++;
}
void Enemy::Damage(int Value){
  HP-=Value;
  STG.Score += Value*10;
  if(HP<=0){
    if(WaveID==1){
      STG.CreateBullet(0,X,Y,1,180);
    }
    if(WaveID==100){
      Lily.Screen.drawString("StageClear!",0,236,2);
      while(1){
        delay(9999);
      }
    }
    Clear();
    STG.Score+=1000;
  }
}